mapper.select:
SELECT a.FINPROD_ID AS finprodId, /**金融产品代码**/ a.FINPROD_TYPE AS finprodType, /**金融产品类型**/ a.FINPROD_ABBR AS finprodAbbr, /**金融产品简称**/ a.FINPROD_NAME AS finprodName, /**金融产品全称**/ a.PROFIT_TYPE AS profitType, /**收益类型**/ a.COUPON_SPECIES AS couponSpecies, /**息票品种**/ a.CHL_FINPROD_ID AS chlFinprodId, /**通道代码**/ a.FINPROD_MARKET_ID AS finprodMarketId, /**市场代码**/ a.ISSUE_PRICE AS issuePrice, /**发行价**/ a.ISSUE_AMT AS issueAmt, /**发行规模**/ a.CCY AS ccy, /**币种**/ a.BLN_AREA AS blnArea, /**境内外**/ a.CALENDAR_ID AS calendarId, /**交易日历**/ a.TRADE_MARKET AS tradeMarket, /**交易场所**/ a.ISSUE_TYPE AS issueType, /**发行方式**/ a.ISSUER AS issuer, /**发行人**/ a.IDATE AS idate, /**发行日**/ a.VDATE AS vdate, /**起息日**/ a.MDATE AS mdate, /**到期日**/ a.ACTMDATE AS actmdate, /**实际到期日**/ a.IS_CHL AS isChl, /**是否通道**/ a.IS_SUS AS isSus, /**是否永续**/ a.IS_RIGHT AS isRight, /**是否含权**/ a.EXE_DATE exeDate, /**含权债摊销日**/ a.P_FINPROD_ID AS pFinprodId, /**母金融产品代码**/ a.O_FINPROD_ID AS oFinprodId, /**原金融产品代码**/ ofpd.finprod_type AS oFinprodType, /**原金融产品类型**/
b.SALE_LAYER AS saleLayer, /**销售分层**/ b.SALE_PERIOD AS salePeriod, /**销售期次**/ a.OPERATION_TYPE AS openType, /**开放类型**/
/* b.CARRYOVER_FREQ AS carryoverFreq,*/ /**基金结转频率**/ /* d.PAY_CYCLE AS carryoverFreq,*/ /**一体化项目，基金结转频率取现金流支付规则表的支付频率**/ null AS carryoverFreq,/**针对一体化表结构变更：【基金结转频率删除：已转移到现金流支付规则表】。由于标的关联支付规则会出现多条，导致共通方法【查询标的信息】报错，暂时【结转频率】先取空，后期确认解决。**/
b.PUR_SPEED AS purSpeed, /**申购确认速度**/ b.RED_SPEED AS redSpeed, /**赎回确认速度**/ b.IS_COMPOUND_INT AS isCompoundInt, /**add by yanya on 20191012 start 增加面值查询字段 start**/ b.face_value AS faceValue,/**面值**/ /**add by yanya on 20191012 start 增加面值查询字段 end**/ c.TYPE_1 AS type1, /**分类1**/ c.TYPE_2 AS type2, /**分类2**/ c.TYPE_3 AS type3, /**分类3**/ c.TYPE_4 AS type4, /**分类4**/ c.TYPE_5 AS type5, /**分类5**/ c.TYPE_6 AS type6, /**分类6**/ c.TYPE_18 AS type18, /**分类18,证券代码**/ a.REGIST_ORG registOrg, /**登记托管机构**/ /** add by yanya on 20201217 增加是否其他债券的查询 **/ /**NVL(b.IS_QTZQ, 'N') isQtzq 是否其他债券**/ 'N' AS isQtzq /**不走其他债权场景**/ FROM FIN_PRODUCT a left join FIN_PRODUCT ofpd on ofpd.finprod_id = a.finprod_id LEFT JOIN FIN_PRODUCT_ADD b ON a.finprod_id = b.finprod_id LEFT JOIN FIN_PRODUCT_TYPE c ON a.finprod_id = c.finprod_id
/**LEFT JOIN FIN_CASH_PAY_RULE d ON d.FINPROD_ID = a.FINPROD_ID AND d.FINPROD_TYPE = a.FINPROD_TYPE**/
WHERE 1=1 and a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} /**金融产品代码**/
and a.finprod_Type=#{finprodType}
union all SELECT a.FINPROD_ID AS finprodId, /**金融产品代码**/ a.FINPROD_TYPE AS finprodType, /**金融产品类型**/ null AS finprodAbbr, /**金融产品简称**/ null as finprodName, /**金融产品全称**/ a.PROFIT_TYPE AS profitType, /**收益类型**/ null AS couponSpecies, /**息票品种**/ a.chl_agrt_id AS chlFinprodId, /**通道代码**/ null AS finprodMarketId, /**市场代码**/ null AS issuePrice, /**发行价**/ null AS issueAmt, /**发行规模**/ a.CCY AS ccy, /**币种**/ null AS blnArea, /**境内外**/ a.CALENDAR_ID AS calendarId, /**交易日历**/ a.TRADE_MARKET AS tradeMarket, /**交易场所**/ null AS issueType, /**发行方式**/ null AS issuer, /**发行人**/ null AS idate, /**发行日**/ a.VDATE AS vdate, /**起息日**/ a.MDATE AS mdate, /**到期日**/ a.mdate AS actmdate, /**实际到期日**/ null AS isChl, /**是否通道**/ null AS isSus, /**是否永续**/ null AS isRight, /**是否含权**/ null as exeDate, /**含权债摊销日**/ null AS pFinprodId, /**母金融产品代码**/ null AS oFinprodId, /**原金融产品代码**/ null AS oFinprodType, /**原金融产品类型**/
null AS saleLayer, /**销售分层**/ null AS salePeriod, /**销售期次**/ null AS openType, /**开放类型**/ null AS carryoverFreq, /**基金结转频率**/ null AS purSpeed, /**申购确认速度**/ null AS redSpeed, /**赎回确认速度**/ null AS isCompoundInt, /**add by yanya on 20191012 start 增加面值查询字段 start**/ null AS faceValue,/**面值**/ /**add by yanya on 20191012 start 增加面值查询字段 end**/ c.TYPE_1 AS type1, /**分类1**/ c.TYPE_2 AS type2, /**分类2**/ c.TYPE_3 AS type3, /**分类3**/ null AS type4, /**分类4**/ null AS type5, /**分类5**/ null AS type6, /**分类6**/ c.TYPE_18 AS type18, /**分类18,证券代码**/ null registOrg, /**登记托管机构**/ /** add by yanya on 20201217 增加是否其他债券的查询 **/ /**NVL(b.IS_QTZQ, 'N') isQtzq 是否其他债券**/ 'N' AS isQtzq /**不走其他债权场景**/ FROM FIN_trade_PRODUCT a LEFT JOIN FIN_PRODUCT_ADD b ON a.finprod_id = b.finprod_id LEFT JOIN FIN_PRODUCT_TYPE c ON a.finprod_id = c.finprod_id WHERE 1=1 and a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} /**金融产品代码**/
and a.finprod_Type=#{finprodType}
and a.branch= #{branch}

SELECT vsd.SCHEME_DETAIL_ID AS schemeDetailId, vsd.SCHEME_ID AS schemeId, vsd.TRADE_MARKET AS tradeMarket, vsd.SEC_TYPE AS secType, vsd.SEC_DETAIL_TYPE AS secDetailType, vsd.INV_AIM AS invAim, vsd.VALUATION_METHOD AS valuationMethod, vsd.VALUATION_PRICE AS valuationPrice, vsd.VALUATION_PRICE_2 AS valuationPrice2, vsd.QUOTA_DIGIT AS quotaDigit, vsd.VALUATION_DATE AS valuationDate, vsd.VDATE AS vdate, vsd.MDATE AS mdate, vsd.VALUATION_SOURCE AS valuationSource, vsd.PRICE_CLASS AS priceClass, vsd.PRICE_TAIL_MODE AS priceTailMode FROM BOK_BOOKSET_PLAN bvp INNER JOIN BOK_VAL_SCHEME vs ON vs.SCHEME_ID = bvp.SCHEME_ID INNER JOIN BOK_VAL_SCHEME_DETAIL vsd ON vsd.SCHEME_ID = bvp.SCHEME_ID AND vsd.VDATE <= #{happenDate} AND vsd.SEC_TYPE = #{secType}
AND vsd.TRADE_MARKET=#{tradeMarket}
AND (vsd.SEC_DETAIL_TYPE=#{secDetailType} OR SEC_DETAIL_TYPE IS NULL)
AND vsd.INV_AIM=#{invAim}
WHERE bvp.BOOKSET_ID = #{booksetId} AND bvp.SCHEME_TYPE = #{schemeType} ORDER BY vsd.VDATE desc ,vsd.SEC_DETAIL_TYPE NULLS LAST

SELECT vsd.SCHEME_DETAIL_ID AS schemeDetailId, vsd.SCHEME_ID AS schemeId, vsd.TRADE_MARKET AS tradeMarket, vsd.SEC_TYPE AS secType, vsd.SEC_DETAIL_TYPE AS secDetailType, vsd.INV_AIM AS invAim, vsd.VALUATION_METHOD AS valuationMethod, vsd.VALUATION_PRICE AS valuationPrice, vsd.VALUATION_PRICE_2 AS valuationPrice2, vsd.QUOTA_DIGIT AS quotaDigit, vsd.VALUATION_DATE AS valuationDate, vsd.VDATE AS vdate, vsd.MDATE AS mdate, vsd.PRICE_CLASS AS priceClass, vsd.PRICE_TAIL_MODE AS priceTailMode FROM BOK_VAL_SCHEME vs INNER JOIN BOK_VAL_SCHEME_DETAIL vsd ON vsd.SCHEME_ID = vs.SCHEME_ID WHERE vsd.VDATE <= #{happenDate} AND vs.ISDEFAULT = #{isdefault} AND vsd.SEC_TYPE = #{secType}
AND vsd.TRADE_MARKET=#{tradeMarket}
AND (vsd.SEC_DETAIL_TYPE=#{secDetailType} OR SEC_DETAIL_TYPE IS NULL)
AND vsd.INV_AIM=#{invAim}
ORDER BY vsd.SEC_DETAIL_TYPE NULLS LAST,vsd.VDATE desc

SELECT detail.SCHEME_DETAIL_ID AS schemeDetailId, detail.SCHEME_ID AS schemeId, detail.TRADE_MARKET AS tradeMarket, detail.SEC_TYPE AS secType, detail.SEC_DETAIL_TYPE AS secDetailType, detail.VALUATION_PRICE AS valuationPrice, detail.VALUATION_PRICE_2 AS valuationPrice2, detail.QUOTA_DIGIT AS quotaDigit, detail.QUOTA_DEC_TYPE AS quotaDecType, detail.VALUATION_DATE AS valuationDate, detail.VDATE AS vdate, detail.PRICE_CLASS AS priceClass FROM BOK_BOOKSET_PLAN bbp INNER JOIN BOK_SCHEME_INFO info ON info.SCH_ID = bbp.SCHEME_ID AND info.SCHEME_TYPE = bbp.SCHEME_TYPE INNER JOIN BOK_SHADOW_PRICE_DETAIL detail ON detail.SCHEME_ID = info.SCH_ID AND detail.VDATE <= #{happenDate} AND detail.SEC_TYPE = #{secType}
AND detail.TRADE_MARKET=#{tradeMarket}
AND (detail.SEC_DETAIL_TYPE=#{secDetailType} OR detail.SEC_DETAIL_TYPE IS NULL)
WHERE bbp.BOOKSET_ID = #{booksetId} AND bbp.SCHEME_TYPE = #{schemeType} ORDER BY detail.VDATE desc ,detail.SEC_DETAIL_TYPE NULLS LAST

SELECT detail.SCHEME_DETAIL_ID AS schemeDetailId, detail.SCHEME_ID AS schemeId, detail.TRADE_MARKET AS tradeMarket, detail.SEC_TYPE AS secType, detail.SEC_DETAIL_TYPE AS secDetailType, detail.VALUATION_PRICE AS valuationPrice, detail.VALUATION_PRICE_2 AS valuationPrice2, detail.QUOTA_DIGIT AS quotaDigit, detail.QUOTA_DEC_TYPE AS quotaDecType, detail.VALUATION_DATE AS valuationDate, detail.VDATE AS vdate, detail.PRICE_CLASS AS priceClass FROM BOK_SCHEME_INFO info INNER JOIN BOK_SHADOW_PRICE_DETAIL detail ON detail.SCHEME_ID = info.SCH_ID WHERE detail.VDATE <= #{happenDate} AND info.IS_DEFAULT = #{isdefault} AND detail.SEC_TYPE = #{secType} AND info.SCHEME_TYPE = #{schemeType}
AND detail.TRADE_MARKET=#{tradeMarket}
AND (detail.SEC_DETAIL_TYPE=#{secDetailType} OR detail.SEC_DETAIL_TYPE IS NULL)
ORDER BY detail.VDATE desc,detail.SEC_DETAIL_TYPE NULLS LAST

SELECT a.FINPROD_ID AS finprodId, /**金融产品代码**/ a.FINPROD_TYPE AS finprodType, /**金融产品类型**/ a.VAL_DATE AS valDate, /**估值日期**/ a.VALUATION AS valuation /**估值**/ FROM FIN_PRODUCT_VALUATION a WHERE a.FINPROD_ID = #{finprodId} AND a.VAL_DATE IN
#{item}
ORDER BY a.VAL_DATE ASC

select * from BOK_DETAIL_ID bokdeal
where 1=1

	and bokdeal.bookset_Id=#{booksetId}


	and bokdeal.bok_detail_id=#{bokdetailId}


select 
	max(deal.branch) branch 
from FIN_TRADE_PRODUCT deal 
where  1=1

	and deal.finprod_Id=#{finprodId}


	and deal.finprod_Type=#{finprodType}


select 
	deal.branch
from FIN_TRADE_PRODUCT deal 
where  1=1

	and deal.finprod_Id=#{finprodId}


	and deal.finprod_Type=#{finprodType}


	and deal.BRANCH_TYPE=#{branchType}


	and deal.mdate=#{mdate}

and rownum = 1

SELECT CASH_ID, EXERCISE_TYPE, VDATE, MDATE, EXERCISE_DATE, EXERCISE_STATUS, EXERCISE_PRICE, EXERCISE_REMARK, FINPROD_ID, FINPROD_TYPE, BRANCH, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME FROM FIN_EXERCISE_PLAN WHERE 1 = 1
AND FINPROD_ID=#{finprodId}
AND FINPROD_TYPE=#{finprodType}
AND EXERCISE_DATE > #{exerciseDate}
AND EXERCISE_TYPE=#{exerciseType}
ORDER BY EXERCISE_DATE ASC

select c.SCHEME_DETAIL_ID AS schemeDetailId, c.SCHEME_ID AS schemeId, c.TRADE_MARKET AS tradeMarket, c.SEC_TYPE AS secType, c.SEC_DETAIL_TYPE AS secDetailType, c.INV_AIM AS invAim, c.VALUATION_METHOD AS valuationMethod, c.VALUATION_PRICE AS valuationPrice, c.VALUATION_PRICE_2 AS valuationPrice2, c.QUOTA_DIGIT AS quotaDigit, c.VALUATION_DATE AS valuationDate, c.VDATE AS vdate, NVL(c.mdate,TO_DATE('2099-12-31','yyyy-MM-dd')) AS mdate, c.PRICE_CLASS AS priceClass, c.PRICE_TAIL_MODE as priceTailMode
from BOK_BOOKSET_PLAN a inner join BOK_VAL_SCHEME b on a.scheme_id = b.scheme_id inner join BOK_VAL_SCHEME_DETAIL_SPECIAL c on c.scheme_id = b.scheme_id and #{happenDate} >= c.vdate and NVL(c.mdate,TO_DATE('2099-12-31','yyyy-MM-dd')) >= #{happenDate} and c.finprod_id = #{finprodId}
where a.scheme_type = #{schemetype} /**方案类型：估值方案**/ and a.bookset_id = #{bokSetId} /**账套代码**/

SELECT fccr.CASH_ID as cashId, fccr.EFF_DATE as effDate, fccr.CAWLBACK_RULE as cawlbackRule, fccr.CAWLBACK_TYPE as cawlbackType, fccr.BASIS as basis, fccr.ACT_RULE as actRule, fci.CASH_TYPE_1 as cashType1, fci.CASH_TYPE_2 as cashType2, fci.FINPROD_ID as finprodId, fci.FINPROD_TYPE as finprodType, fci.BRANCH as branch FROM FIN_CLAWBACK_CALC_RULE fccr LEFT JOIN FIN_CASH_INFO fci ON fccr.CASH_ID = fci.CASH_ID WHERE fci.CASH_ID = #{cashId,jdbcType=VARCHAR}
AND fci.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
AND fci.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND fci.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND fccr.EFF_DATE <= #{effdateEnd,jdbcType=DATE}
AND ( EXISTS ( SELECT TMP.CASH_ID,TMP.EFF_DATE FROM ( SELECT CASH_ID, MAX(EFF_DATE) AS EFF_DATE FROM FIN_CLAWBACK_CALC_RULE WHERE EFF_DATE <= #{effdateStart,jdbcType=DATE} GROUP BY CASH_ID ) TMP WHERE TMP.CASH_ID = fci.CASH_ID AND TMP.EFF_DATE = fccr.EFF_DATE ) OR fccr.EFF_DATE >= #{effdateStart,jdbcType=DATE} )
AND fci.BRANCH = #{branch,jdbcType=DATE}
ORDER BY fci.CASH_TYPE_2,fccr.EFF_DATE

SELECT * FROM( SELECT MEQ.EXCHARGE_CODE exchargeCode, MEQ.TRADE_DATE tradeDate, MEQ.DATASOURCE_TYPE datasourceType, MEQ.OPEN_PRICE openPrice, MEQ.CLOSE_PRICE closePrice, MEQ.HIGH_PRICE highPrice, MEQ.LOW_PRICE lowPrice, MEQ.MID_PRICE midPrice, MEQ.BASIS_CYY basisCyy, MEQ.QUOT_CYY quotCyy, MEQ.QUOT_UNIT quotUnit, MEQ.INPUT_TYPE inputType FROM MST_EXCHARGE_QUOTE MEQ WHERE 1=1
AND MEQ.BASIS_CYY =#{basicCny}
AND MEQ.QUOT_CYY =#{offreCny}
AND MEQ.DATASOURCE_TYPE=#{valuation}
AND MEQ.TRADE_DATE < =#{serchDate}
ORDER BY MEQ.TRADE_DATE DESC ) WHERE ROWNUM = 1

SELECT * FROM( SELECT MVI.FINPROD_ID2 finprodId2, MVI.DATASOURCE_TYPE datasourceType, MVI.VAL_DATE valDate, MVI.VALUATION valuation, MVI.VALMODEL_ID valmodelId, MVI.CCY ccy, MVI.INPUT_TYPE inputType FROM MST_VAL_IRS MVI WHERE 1=1
AND MVI.DATASOURCE_TYPE = #{datasourceType}
AND MVI.FINPROD_ID2 = #{finprodId2}
AND MVI.VAL_DATE <=#{valDate}
ORDER BY MVI.VAL_DATE DESC ) WHERE ROWNUM = 1

SELECT * FROM( SELECT MVI.FINPROD_ID2 finprodId2, MVI.DATASOURCE_TYPE datasourceType, MVI.VAL_DATE valDate, MVI.VALUATION valuation, MVI.VALMODEL_ID valmodelId, MVI.CCY ccy, MVI.INPUT_TYPE inputType FROM MST_VAL_FX MVI WHERE 1=1
AND MVI.DATASOURCE_TYPE = #{datasourceType}
AND MVI.FINPROD_ID2 = #{finprodId2}
AND MVI.VAL_DATE <=#{valDate}
ORDER BY MVI.VAL_DATE DESC ) WHERE ROWNUM = 1

SELECT * FROM( SELECT MSP.SHARES_ID sharesId, MSP.DEAL_DATE dealDate, MSP.PRE_CLOSE_PRICE preClosePrice, MSP.OPEN_PRICE openPrice, MSP.HIGH_PRICE highPrice, MSP.LOW_PRICE lowPrice, MSP.CLOSE_PRICE closePrice, MSP.AVG_PRICE avgPrice, MSP.TRADE_STATUS tradeStatus, MSP.INPUT_TYPE inputType FROM MST_SHARE_PRICE MSP WHERE 1=1
AND MSP.SHARES_ID = #{sharesId}
AND MSP.DEAL_DATE <=#{dealDate}
ORDER BY MSP.DEAL_DATE DESC ) WHERE ROWNUM = 1

SELECT * FROM( select MSL.SHARES_ID sharesId, MSL.VAL_DATE valDate, MSL.RATIO ratio, MSL.M_DATE mDate, MSL.ISSUE_DATE issueDate, MSL.INDUSTRY industry, MSL.INDUSTRY_INDEX industryIndex, MSL.LIMITATION_PERIOD limitationPeriod, MSL.INPUT_TYPE inputType from MST_SHARE_LQRATIO MSL where 1=1
AND MSL.SHARES_ID = #{sharesId}
AND MSL.VAL_DATE <=#{valDate}
ORDER BY MSL.VAL_DATE DESC ) WHERE ROWNUM = 1

select
	SUM(tpd.TRADE_AMT) tradeAmt,
	tpd.TRADE_DATE tradeDate,
	tpd.MDATE mdate
from TRD_PRODUCT_DEAL tpd
inner join TRD_PRODUCT_DEAL_ADD tpda on tpd.trade_id =tpda.trade_id
LEFT JOIN FIN_PRODUCT fp  on fp.finprod_id = tpda.portfolio_id
where 1=1
and tpd.FINPROD_ID=#{finprodId}
and decode(fp.finprod_id,null,'F16_'||tpda.portfolio_id,tpda.portfolio_id)  = #{prodId}
and tpd.FINPROD_TYPE2 ='F01'
and tpd.MDATE=#{mdate}
and tpd.IS_CANCEL='N'
and tpd.TRADE_STATUS='01'

	and tpd.PS= #{ps}


	and tpd.sec_manage_acct_id = #{secManageAcctId}


	and tpd.chl_id = #{chlId}


	and tpd.inv_aim = #{invAim}

GROUP by tpd.TRADE_DATE,tpd.MDATE
